import json
import re

from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema.message import Message


class MiraRiskJSONValidator(Component):
    display_name = "Mira Risk JSON Validator"
    description = "Validates grounded risks, provisional scores, and rankings."
    icon = "shield-check"
    name = "MiraRiskJSONValidator"

    # Exact categories from project_risks(2).csv
    SOURCE_CATEGORIES = {
        "R01": "Data Quality & Availability",
        "R02": "Integration Issues",
        "R03": "Talent & Skills Gap",
        "R04": "Change Resistance",
        "R05": "Ethical & Legal Concerns",
        "R06": "Cost Overruns",
        "R07": "Unrealistic Expectations",
        "R08": "Model Performance Drift",
        "R09": "Security Vulnerabilities",
        "R10": "Vendor Lock-in",
    }

    # Proposed T3 assessment, NOT values from the CSV.
    BASELINE_V1 = {
        "R01": ("High", "High"),
        "R02": ("Medium", "High"),
        "R03": ("High", "Medium"),
        "R04": ("Medium", "Medium"),
        "R05": ("Medium", "High"),
        "R06": ("Medium", "High"),
        "R07": ("Medium", "Medium"),
        "R08": ("Medium", "High"),
        "R09": ("Medium", "High"),
        "R10": ("Medium", "Medium"),
    }

    LEVELS = {"Low": 1, "Medium": 2, "High": 3}

    inputs = [
        MessageTextInput(
            name="model_response",
            display_name="Model Response",
            required=True,
        ),
        MessageTextInput(
            name="user_request",
            display_name="User Request",
            required=True,
        ),
    ]

    outputs = [
        Output(
            name="validated_response",
            display_name="Validated Response",
            method="validate_json",
        ),
    ]

    @staticmethod
    def as_text(value):
        if hasattr(value, "text"):
            value = value.text
        return str(value or "").strip()

    @staticmethod
    def get_priority(score):
        if score >= 6:
            return "High"
        if score >= 3:
            return "Medium"
        return "Low"

    def validate_json(self) -> Message:
        raw = self.as_text(self.model_response)
        request = self.as_text(self.user_request)

        raw = re.sub(
            r"^```(?:json)?\s*|\s*```$",
            "",
            raw,
            flags=re.IGNORECASE,
        ).strip()

        errors = []

        try:
            data = json.loads(raw)
        except json.JSONDecodeError as exc:
            return Message(text=json.dumps({
                "validation_status": "FAIL",
                "errors": [f"Invalid JSON: {exc.msg}"],
            }, indent=2))

        if not isinstance(data, dict):
            return Message(text=json.dumps({
                "validation_status": "FAIL",
                "errors": ["Root must be a JSON object."],
            }, indent=2))

        status = data.get("status")
        if status not in {"SUCCESS", "INSUFFICIENT_INFORMATION"}:
            errors.append("Invalid or missing status.")

        for field in ["project_name", "assessment_summary"]:
            if not isinstance(data.get(field), str):
                errors.append(f"{field} must be a string.")

        array_fields = [
            "risks",
            "missing_information",
            "clarifying_questions",
            "sources_used",
        ]

        for field in array_fields:
            if not isinstance(data.get(field), list):
                errors.append(f"{field} must be an array.")
            elif field != "risks":
                for i, item in enumerate(data[field]):
                    if not isinstance(item, str):
                        errors.append(f"{field}[{i}] must be a string.")

        risks = data.get("risks")
        if not isinstance(risks, list):
            risks = []

        # Determine whether the request explicitly identifies ABCDE.
        is_abcde = bool(re.search(
            r"\bABCDE\b", request, flags=re.IGNORECASE
        ))

        # Support "top 3", "top three", etc.
        number_words = {
            "one": 1, "two": 2, "three": 3,
            "four": 4, "five": 5, "six": 6,
            "seven": 7, "eight": 8,
            "nine": 9, "ten": 10,
        }

        top_match = re.search(
            r"\btop\s+(\d+|one|two|three|four|five|six|"
            r"seven|eight|nine|ten)\b",
            request,
            flags=re.IGNORECASE,
        )

        top_n = None
        if top_match:
            value = top_match.group(1).lower()
            top_n = (
                int(value) if value.isdigit()
                else number_words[value]
            )

        # Treat an unqualified assessment request as a full assessment.
        full_assessment = (
            is_abcde
            and top_n is None
            and bool(re.search(
                r"\b(risk assessment|assess risks|all risks)\b",
                request,
                flags=re.IGNORECASE,
            ))
        )

        if status == "INSUFFICIENT_INFORMATION":
            if risks:
                errors.append(
                    "Insufficient-information response must have risks=[]."
                )
            if not data.get("missing_information"):
                errors.append("Missing information must be identified.")
            if not data.get("clarifying_questions"):
                errors.append("Clarifying questions are required.")

        if status == "SUCCESS":
            if not risks:
                errors.append("Successful assessment must contain risks.")

            # Prevent unrelated or vague requests from borrowing ABCDE data.
            if not is_abcde:
                errors.append(
                    "Project not explicitly identified as ABCDE; "
                    "cannot validate using ABCDE grounding."
                )

        seen_ids = set()
        actual_ids = []

        for i, risk in enumerate(risks):
            prefix = f"risks[{i}]"

            if not isinstance(risk, dict):
                errors.append(f"{prefix} must be an object.")
                continue

            string_fields = [
                "risk_id", "category", "description",
                "likelihood", "impact", "priority",
                "mitigation", "contingency", "source",
                "assessment_basis",
            ]

            for field in string_fields:
                if not isinstance(risk.get(field), str):
                    errors.append(f"{prefix}.{field} must be a string.")

            risk_id = risk.get("risk_id")
            if not isinstance(risk_id, str):
                continue

            actual_ids.append(risk_id)

            if risk_id in seen_ids:
                errors.append(f"{prefix}: duplicate risk_id {risk_id}.")
            seen_ids.add(risk_id)

            if risk_id not in self.SOURCE_CATEGORIES:
                errors.append(f"{prefix}: unknown source ID {risk_id}.")
                continue

            expected_category = self.SOURCE_CATEGORIES[risk_id]
            if risk.get("category") != expected_category:
                errors.append(
                    f"{prefix}: expected category {expected_category}."
                )

            if risk.get("source") != "project_risks(2).csv":
                errors.append(
                    f"{prefix}: expected source project_risks(2).csv."
                )

            expected_likelihood, expected_impact = (
                self.BASELINE_V1[risk_id]
            )

            if risk.get("likelihood") != expected_likelihood:
                errors.append(
                    f"{prefix}: expected provisional likelihood "
                    f"{expected_likelihood}."
                )

            if risk.get("impact") != expected_impact:
                errors.append(
                    f"{prefix}: expected provisional impact "
                    f"{expected_impact}."
                )

            expected_score = (
                self.LEVELS[expected_likelihood]
                * self.LEVELS[expected_impact]
            )

            score = risk.get("risk_score")
            if type(score) is not int or score != expected_score:
                errors.append(
                    f"{prefix}: expected risk_score {expected_score}."
                )

            expected_priority = self.get_priority(expected_score)
            if risk.get("priority") != expected_priority:
                errors.append(
                    f"{prefix}: expected priority {expected_priority}."
                )

            if not risk.get("assessment_basis"):
                errors.append(
                    f"{prefix}: assessment_basis is required."
                )

        if status == "SUCCESS" and is_abcde:
            expected_ranking = sorted(
                self.BASELINE_V1,
                key=lambda rid: (
                    -self.LEVELS[self.BASELINE_V1[rid][0]]
                    * self.LEVELS[self.BASELINE_V1[rid][1]],
                    rid,
                ),
            )

            if top_n is not None:
                expected_ids = expected_ranking[:top_n]

                if actual_ids != expected_ids:
                    errors.append(
                        "Incorrect top-N ranking. "
                        f"Expected {expected_ids}; got {actual_ids}."
                    )

            elif full_assessment:
                expected_ids = set(self.SOURCE_CATEGORIES)

                if set(actual_ids) != expected_ids:
                    missing = sorted(expected_ids - set(actual_ids))
                    extra = sorted(set(actual_ids) - expected_ids)

                    errors.append(
                        "Full assessment must cover all 10 risks. "
                        f"Missing: {missing}; unexpected: {extra}."
                    )
      
                # Verify full-assessment ranking order as well.
                if (
                    set(actual_ids) == expected_ids
                    and actual_ids != expected_ranking
                ):
                    errors.append(
                        "Incorrect full-assessment order. "
                        f"Expected {expected_ranking}; "
                        f"got {actual_ids}."
                    )

        result = (
            {"validation_status": "FAIL", "errors": errors}
            if errors else
            {"validation_status": "PASS", "validated_data": data}
        )

        return Message(text=json.dumps(result, indent=2))
